insert into resources (slug, title, description, label, keyword, category, tags, kind, featured, unlisted, status, published_at, blocks)
values ('claude-video-editing', 'איך לגרום ל־Claude Code לערוך בשבילך וידאו', 'שלושה שלבים והפרומפטים מהסרטון: להתקין את Claude Code, לתת לו את הכלים לעריכה וללמד אותו את הסגנון שלך.', 'LAB', 'עריכה', 'ai',
  array['claude-code', 'video', 'remotion']::text[], 'free', false, true, 'published', now(),
  '[{"id":"seed0101","type":"text","text":"בסרטון הראיתי איך לגרום ל־Claude Code לערוך לך וידאו. פה יש הכול במקום אחד: כל שלב, כל פרומפט ואיך מגדירים סגנון משלך. תעתיק, תדביק ותתחיל.","variant":"plain"},{"id":"seed0102","type":"text","text":"**מה צריך:** Claude Code על המחשב והסרטונים שלך. את שאר הכלים Claude Code מתקין בעצמו, אתה רק נותן לו את הפרומפט.","variant":"tip"},{"id":"seed0103","type":"heading","text":"שלב 1: Claude Code ותיקייה אחת","level":2},{"id":"seed0104","type":"text","text":"תוריד את Claude Code כאפליקציה למחשב ולא כדפדפן. אחרי זה תיצור תיקייה אחת בשם **עריכת AI**, עם שלוש תיקיות בפנים:","variant":"plain"},{"id":"seed0105","type":"text","text":"- **חומר מקורי:** הסרטונים הגולמיים שלך\n- **רפרנסים:** סרטונים שאתה אוהב את הסגנון שלהם\n- **מוכן:** הסרטונים הערוכים","variant":"plain"},{"id":"seed0106","type":"text","text":"תפתח צ''אט חדש ב־Claude Code ותצביע על התיקייה הזאת. זהו, Claude רואה את כל הקבצים שלך.","variant":"plain"},{"id":"seed0107","type":"link","url":"https://code.claude.com/docs/en/overview","title":"Claude Code","description":"ההוראות הרשמיות להתקנה"},{"id":"seed0108","type":"heading","text":"שלב 2: הכלים לעריכה","level":2},{"id":"seed0109","type":"text","text":"במה Claude יערוך את הסרטון? בכלים שקיימים כבר, והוא מתקין אותם בשבילך. תדביק לו את הפרומפט הזה:","variant":"plain"},{"id":"seed0110","type":"prompt","title":"פרומפט 1: להתקין את הכלים","text":"אתה העורך וידאו שלי. תתקין על המחשב שלי את הכלים: Remotion, HyperFrames, FFmpeg, Whisper, yt-dlp (קישורים למטה). תבדוק כל אחד ותגיד לי כשהכול מוכן."},{"id":"seed0111","type":"text","text":"Claude ישאל אותך אם לאשר את ההתקנות. תקרא מה הוא מבקש להריץ ורק אז תאשר.","variant":"tip"},{"id":"seed0112","type":"text","text":"מה כל כלי עושה:","variant":"plain"},{"id":"seed0113","type":"text","text":"- **Remotion:** יצירת וידאו מקוד\n- **HyperFrames:** עוד כלי ליצירת וידאו מקוד\n- **FFmpeg:** חיתוך, חיבור והמרה של וידאו ואודיו\n- **Whisper:** תמלול דיבור לטקסט, בסיס לכתוביות\n- **yt-dlp:** הורדת סרטונים מהרשת, למשל רפרנסים","variant":"plain"},{"id":"seed0114","type":"link","url":"https://github.com/remotion-dev/remotion","title":"Remotion","description":"github.com/remotion-dev/remotion"},{"id":"seed0115","type":"link","url":"https://github.com/heygen-com/hyperframes","title":"HyperFrames","description":"github.com/heygen-com/hyperframes"},{"id":"seed0116","type":"link","url":"https://github.com/FFmpeg/FFmpeg","title":"FFmpeg","description":"github.com/FFmpeg/FFmpeg"},{"id":"seed0117","type":"link","url":"https://github.com/openai/whisper","title":"Whisper","description":"github.com/openai/whisper"},{"id":"seed0118","type":"link","url":"https://github.com/yt-dlp/yt-dlp","title":"yt-dlp","description":"github.com/yt-dlp/yt-dlp"},{"id":"seed0119","type":"heading","text":"שלב 3: ללמד אותו את הסגנון שלך","level":2},{"id":"seed0120","type":"text","text":"פה ההבדל בין עריכה גנרית לעריכה שנראית כמו שלך. תאסוף סרטונים שאתה אוהב את הסגנון שלהם ותשים אותם בתיקיית **רפרנסים**. אפשר גם לבקש מ־Claude להוריד אותם בשבילך עם yt-dlp.","variant":"plain"},{"id":"seed0121","type":"prompt","title":"פרומפט 2: ללמד אותו את הסגנון","text":"הנה עוד פרומפטים ורפרנסים. תלמד מהם את הסגנון שלי: פונטים, צבעים, כתוביות, מעברים וקצב. תבנה ברנדבוק."},{"id":"seed0122","type":"text","text":"בכל מקרה תן לו גם פרומפטים ורפרנסים משלך. ככל שיש לו יותר חומר ממך, הסגנון שהוא לומד מדויק יותר.","variant":"tip"},{"id":"seed0123","type":"text","text":"התוצאה היא **ברנדבוק**: מסמך שמסכם את הפונטים, הצבעים, הכתוביות, המעברים והקצב שלך. מעכשיו Claude עורך לפיו. תקרא אותו, ואם משהו לא נראה לך, תגיד לו מה לשנות.","variant":"plain"},{"id":"seed0124","type":"heading","text":"עכשיו לערוך","level":2},{"id":"seed0125","type":"text","text":"תשים סרטון בתיקיית **חומר מקורי** ותגיד ל־Claude מה לעשות איתו, כמו שמדברים עם עורך אמיתי. דוגמה לעריכה ראשונה (הפרומפט הזה לא מהסרטון, תתאים אותו לסרטון שלך):","variant":"plain"},{"id":"seed0126","type":"prompt","title":"דוגמה: עריכה ראשונה","text":"תערוך את הסרטון שבתיקיית חומר מקורי לפי הברנדבוק. תוסיף כתוביות ותשמור את התוצאה בתיקיית מוכן."},{"id":"seed0127","type":"text","text":"ואם משהו לא יצא טוב, לא מתחילים מחדש. פשוט תגיד לו מה לתקן, בדיוק כמו לעורך אמיתי:","variant":"plain"},{"id":"seed0128","type":"prompt","title":"פרומפט 3: תיקונים","text":"תתקן את זה, ואת זה, והפריים פה יותר גדול."},{"id":"seed0129","type":"heading","text":"בקצרה","level":2},{"id":"seed0130","type":"text","text":"1. תוריד את Claude Code ותיצור תיקיית **עריכת AI** עם חומר מקורי, רפרנסים ומוכן\n2. תדביק לו את הפרומפט הראשון והוא מתקין את הכלים\n3. תן לו רפרנסים ופרומפט שני, והוא בונה את הברנדבוק שלך\n4. תערוך, ותגיד לו מה לתקן עד שזה נראה כמו שלך","variant":"plain"}]'::jsonb)
